from decimal import Decimal
from typing import Any


def _value(row: dict | None, column: str) -> Any:
    if row is None:
        return ""
    return row.get(column, "")


def _text(value: Any) -> str:
    if value is None:
        return ""
    return str(value)


def _length(value: Any) -> int:
    return len(_text(value))


def _nvl(value: Any, default: Any) -> Any:
    return default if value is None or value == "" else value


def _number(value: Any) -> Decimal:
    if value is None or value == "":
        return Decimal(0)
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    errors: list[dict] = []

    acct_nm = _value(record, "ACCT_NM")
    acct_typ = _value(record, "ACCT_TYP")
    ann_rev = _value(record, "ANN_REV")
    cred_hold = _value(record, "CRED_HOLD")
    cred_limit = _value(record, "CRED_LIMIT")
    region_cd = _value(record, "REGION_CD")

    if event in ("INSERT", "UPDATE"):
        if _length(acct_nm) < 2:
            errors.append(
                {
                    "code": "E1001",
                    "message": "Account name too short",
                    "severity": "BLOCK",
                }
            )

    if event in ("INSERT", "UPDATE"):
        if not (
            acct_typ == "C"
            or acct_typ == "P"
            or acct_typ == "R"
            or acct_typ == "X"
        ):
            errors.append(
                {
                    "code": "E1002",
                    "message": "Invalid account type",
                    "severity": "BLOCK",
                }
            )

    if event in ("INSERT", "UPDATE"):
        if _number(_nvl(ann_rev, 0)) < 0:
            errors.append(
                {
                    "code": "E1003",
                    "message": "Annual revenue negative",
                    "severity": "BLOCK",
                }
            )

    if event == "UPDATE":
        old_cred_hold = _value(old, "CRED_HOLD")
        if (
            old_cred_hold == "Y"
            and cred_hold == "N"
            and _number(cred_limit) <= 0
        ):
            errors.append(
                {
                    "code": "E1004",
                    "message": "Cannot release credit hold with zero credit limit",
                    "severity": "BLOCK",
                }
            )

    if event in ("INSERT", "UPDATE"):
        if _length(region_cd) != 3:
            errors.append(
                {
                    "code": "E1005",
                    "message": "Region code must be 3 chars",
                    "severity": "WARN",
                }
            )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
